// src/components/User/HomePage.js
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './HomePage.css';

// Define the categories and corresponding SVG paths/structure
const CATEGORY_ICONS = {
  Pizza: (
    <svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="12" cy="12" r="10" />
      <path d="M12 2a10 10 0 0 0-7 3m14 0a10 10 0 0 0-7-3" />
      <path d="M12 2a10 10 0 0 1 7 3" />
      <path d="M12 2a10 10 0 0 1-7 3" />
      <circle cx="9" cy="9" r="1" fill="currentColor" />
      <circle cx="15" cy="15" r="1" fill="currentColor" />
      <circle cx="12" cy="15" r="1" fill="currentColor" />
      <circle cx="15" cy="9" r="1" fill="currentColor" />
    </svg>
  ),
  Burger: (
    <svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
      <path d="M11 17H4a2 2 0 0 1-2-2V9a2 2 0 0 1 2-2h7" />
      <path d="M13 17h7a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-7" />
      <path d="M2 9h20" />
      <path d="M2 15h20" />
      <circle cx="12" cy="12" r="2" />
    </svg>
  ),
  Drink: (
    <svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
      <path d="M6 8h12v12a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2V8z" />
      <line x1="12" y1="2" x2="12" y2="8" />
      <line x1="8" y1="2" x2="16" y2="2" />
    </svg>
  ),
  'French fries': (
    <svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
      <path d="M4 10h16" />
      <path d="M10 20v-5" />
      <path d="M14 20v-5" />
      <path d="M6 20v-5" />
      <path d="M18 20v-5" />
      <rect x="3" y="4" width="18" height="16" rx="2" />
      <line x1="9" y1="15" x2="9" y2="4" />
      <line x1="15" y1="15" x2="15" y2="4" />
    </svg>
  ),
  Veggies: (
    <svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
      <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2z" />
      <path d="M15.5 8.5L8.5 15.5" />
      <path d="M15.5 15.5L8.5 8.5" />
      <path d="M10 5l-2 2" />
      <path d="M19 14l2-2" />
      <path d="M14 19l2-2" />
    </svg>
  ),
};

const CATEGORIES = ['Burger', 'Pizza', 'Drink', 'French fries', 'Veggies'];

export default function HomePage({ menu = [], cart = [], addToCart }) {
  const [selectedCategory, setSelectedCategory] = useState('Pizza'); // Default
  const [searchTerm, setSearchTerm] = useState('');
  const navigate = useNavigate();

  // Filter logic
  const filteredMenu = menu.filter(item => {
    const matchesCategory = item.category === selectedCategory;
    const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const cartItemCount = cart.reduce((acc, item) => acc + item.quantity, 0);

  return (
    <div className="mobile-container">
      <header className="home-header">
        <h1>Good evening</h1>
        <p>Place you order here</p>
      </header>

      <div className="search-bar">
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="search-icon">
          <path strokeLinecap="round" strokeLinelinejoin="round" d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" />
        </svg>
        <input 
          type="text" 
          placeholder="Search"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <nav className="category-nav">
        {CATEGORIES.map(category => (
          <button 
            key={category}
            className={`category-btn with-icon ${selectedCategory === category ? 'active' : ''}`}
            onClick={() => setSelectedCategory(category)}
          >
            {/* Display the icon above the text */}
            <div className="category-icon-wrapper">
              {CATEGORY_ICONS[category]}
            </div>
            {category}
          </button>
        ))}
      </nav>

      <section className="menu-list">
        <h2>{selectedCategory}</h2>
        {filteredMenu.map(item => (
          <div key={item.id} className="menu-item">
            <img src={item.image} alt={item.name} className="item-image" />
            <div className="item-details">
              <h3>{item.name}</h3>
              <p>₹{item.price}</p>
            </div>
            <button className="add-btn" onClick={() => addToCart(item)}>+</button>
          </div>
        ))}
      </section>

      {cartItemCount > 0 && (
        <div className="next-button-container">
          <button className="next-btn" onClick={() => navigate('/checkout')}>
            <span>{cartItemCount} Item{cartItemCount > 1 ? 's' : ''}</span>
            <span>Next</span>
          </button>
        </div>
      )}
    </div>
  );
}
